import {TAXA,type TaxonBrief} from './taxa'

/**
 * Image production plan: the master catalog (200 rows) and the self-contained prompts for class-D images.
 * Pure functions only; `build.ts` writes the outputs and `tests/image-plan.test.ts` keeps them honest.
 *
 * Evidence classes: A generated by code from sourced data · B code + licensed scan/template · C licensed photograph or
 * scan render of a real specimen (NEVER generated by AI) · D reconstruction made by an artist/3D or a generator from this brief.
 */
export type EvidenceClass='A'|'B'|'C'|'D'
export type RowStatus='TODO'|'BLOCKED-NO-SPECIMEN'|'NOT-APPLICABLE'
export type MediaKindName='specimen-photo'|'cast-photo'|'reconstruction'|'context-schematic'
export type CatalogRow={
  code:string;taxonId:string|null;series:string;title:string;role:string;mediaKind:MediaKindName;evidenceClass:EvidenceClass
  wave:1|2|3|4|5|6;ratio:string;size:string;status:RowStatus;statusReason:string;specimenRef:string;brief:string;promptFile:string
}

export const CORE_TAXA_ORDER=TAXA.map(taxon=>taxon.id)

const FORMAT={
  square:{ratio:'1:1',size:'512×512'},portrait:{ratio:'4:5',size:'1000×1250'},hero:{ratio:'16:9',size:'1920×1080'},
  plate:{ratio:'4:3',size:'1600×1200'},vector:{ratio:'free (SVG)',size:'vector + 1600 px WebP fallback'},card:{ratio:'1.91:1',size:'1200×630'},
} as const

type Series={code:string;title:(t:TaxonBrief)=>string;role:string;kind:MediaKindName;cls:EvidenceClass;wave:1|2|3;fmt:keyof typeof FORMAT;brief:(t:TaxonBrief)=>string}

const SOURCE_ORDER='Source order: (1) museum or institutional open-access collections, (2) licensed 3D scan repositories (e.g. MorphoSource, Smithsonian) with an explicit licence, (3) Wikimedia Commons with a CC licence. Record institution, catalog number, licence, credit and source URL. Never AI-generated; if no licensed image exists, leave the slot empty.'
const PLATE_RULES='Neutral dark-grey background, even lighting, scale bar in centimetres, specimen in standard orientation (skull on the Frankfurt horizontal plane).'

const SERIES:Series[]=[
  {code:'S01',title:t=>`${t.short}: tree avatar`,role:'tree-thumbnail',kind:'context-schematic',cls:'B',wave:1,fmt:'square',
    brief:t=>`Render of the primary cranium (${t.basis.primary}) in lateral view, square crop, identical camera, light and background preset for all 11 core taxa, legible at 36 px. Built from a licensed scan or cast photograph (see S04 sources); no AI. Must differ visibly from the portrait.`},
  {code:'S02',title:t=>`${t.short}: portrait`,role:'profile-portrait',kind:'reconstruction',cls:'D',wave:1,fmt:'portrait',
    brief:t=>t.noCranium?'Bone-inventory silhouette (no face is rendered because no cranium exists). Prompt provided.':'Scientific facial reconstruction from the cranium. Prompt provided. Requires reference renders (S04/S05), assumptions sheet and review.'},
  {code:'S03',title:t=>`${t.short}: dossier hero`,role:'dossier-hero',kind:'reconstruction',cls:'D',wave:2,fmt:'hero',
    brief:()=>'Wide environmental scene with 2–3 individuals. Prompt provided. Requires assumptions sheet and review.'},
  {code:'S04',title:t=>`${t.short}: cranium, lateral view`,role:'specimen-reference',kind:'specimen-photo',cls:'C',wave:1,fmt:'plate',
    brief:t=>`Lateral view of ${t.basis.primary}. ${PLATE_RULES} ${SOURCE_ORDER}`},
  {code:'S05',title:t=>`${t.short}: cranium, frontal view`,role:'specimen-reference',kind:'specimen-photo',cls:'C',wave:1,fmt:'plate',
    brief:t=>`Frontal view of ${t.basis.primary}. ${PLATE_RULES} ${SOURCE_ORDER}`},
  {code:'S06',title:t=>`${t.short}: jaw and teeth, occlusal view`,role:'specimen-reference',kind:'specimen-photo',cls:'C',wave:2,fmt:'plate',
    brief:t=>`Occlusal view of the best-preserved mandible or maxilla of ${t.short} (${[t.basis.primary,...t.basis.also].join('; ')}). ${PLATE_RULES} ${SOURCE_ORDER}`},
  {code:'S07a',title:t=>`${t.short}: key bone 1 — ${t.keyBones[0]}`,role:'anatomy-plate',kind:'specimen-photo',cls:'C',wave:2,fmt:'plate',
    brief:t=>`${t.keyBones[0]}. ${PLATE_RULES} ${SOURCE_ORDER}`},
  {code:'S07b',title:t=>`${t.short}: key bone 2 — ${t.keyBones[1]}`,role:'anatomy-plate',kind:'specimen-photo',cls:'C',wave:2,fmt:'plate',
    brief:t=>`${t.keyBones[1]}. ${PLATE_RULES} ${SOURCE_ORDER}`},
  {code:'S08',title:t=>`${t.short}: annotated anatomy diagram`,role:'anatomy-plate',kind:'context-schematic',cls:'B',wave:3,fmt:'vector',
    brief:t=>`Vector diagram traced from the S04/S05 images. Label at most six diagnostic traits, each backed by a sourced claim: ${t.diagnostic.join('; ')}. Label text comes from claim records, not free text.`},
  {code:'S09',title:t=>`${t.short}: scale against an adult human`,role:'scale-reference',kind:'context-schematic',cls:'A',wave:3,fmt:'vector',
    brief:t=>`Generated by script: height and mass drawn as uncertainty BANDS next to a 170 cm adult-human silhouette, labelled “estimate”. Source ranges: ${t.body}. No individual-looking figure.`},
  {code:'S10',title:t=>`${t.short}: habitat`,role:'habitat',kind:'reconstruction',cls:'D',wave:1,fmt:'hero',
    brief:()=>'Paleoenvironment landscape with NO hominins. Prompt provided. Fauna kinds must be verified against the site faunal list.'},
  {code:'S11',title:t=>`${t.short}: ${t.behavior?t.behavior.title:'behaviour'}`,role:'behavior',kind:'reconstruction',cls:'D',wave:3,fmt:'plate',
    brief:t=>t.behavior?'Behaviour scene limited to what the evidence documents. Prompt provided.':'No source-supported behaviour exists; the slot stays empty until evidence is registered.'},
  {code:'S12',title:t=>`${t.short}: type or principal site`,role:'context',kind:'specimen-photo',cls:'C',wave:2,fmt:'hero',
    brief:t=>`Photograph of ${t.typeSite} (landscape or excavation). Licensed; if none exists, use a licensed landscape photograph with a site marker and say so in the caption. ${SOURCE_ORDER}`},
  {code:'S13',title:t=>`${t.short}: sites and range map`,role:'context',kind:'context-schematic',cls:'A',wave:1,fmt:'vector',
    brief:t=>`Generated by script from the site records linked to ${t.short} and the paleo pipeline (phase P3) at the taxon's time slice; uncertainty drawn as soft areas.`},
  {code:'S14',title:t=>`${t.short}: which parts of the skeleton are known`,role:'anatomy-plate',kind:'context-schematic',cls:'B',wave:3,fmt:'vector',
    brief:t=>`Skeleton-inventory diagram: a base skeleton template with the preserved elements highlighted, element list taken from the specimen record(s): ${[t.basis.primary,...t.basis.also].join('; ')}.`},
]

