const pad=(n:number)=>String(n).padStart(2,'0')
const fmtOf=(key:keyof typeof FORMAT)=>FORMAT[key]
const PROMPT_FILE=(taxonId:string)=>`prompts/${taxonId}.md`

function statusFor(taxon:TaxonBrief,series:string):{status:RowStatus;reason:string}{
  if(series.startsWith('L')&&!taxon.lithics) return {status:'NOT-APPLICABLE',reason:taxon.noLithicsReason}
  if(series==='S11'&&!taxon.behavior) return {status:'NOT-APPLICABLE',reason:'No source-supported behaviour for this taxon; revisit only when evidence is registered.'}
  if(taxon.basis.catalogIds.length===0) return {status:'BLOCKED-NO-SPECIMEN',reason:'No specimen record exists in content/specimens.ts yet; no image may be made before it exists.'}
  return {status:'TODO',reason:''}
}

export function buildCatalog():CatalogRow[]{
  const rows:CatalogRow[]=[]
  for(const taxon of TAXA){
    const specimenRef=[taxon.basis.primary,...taxon.basis.also].join(' | ')
    for(const series of SERIES){
      const format=fmtOf(series.fmt)
      const {status,reason}=statusFor(taxon,series.code)
      rows.push({code:`${taxon.id}.${series.code}`,taxonId:taxon.id,series:series.code,title:series.title(taxon),role:series.role,mediaKind:series.kind,evidenceClass:series.cls,wave:series.wave,ratio:format.ratio,size:format.size,status,statusReason:reason,specimenRef,brief:series.brief(taxon),promptFile:series.cls==='D'&&status!=='NOT-APPLICABLE'?PROMPT_FILE(taxon.id):''})
    }
    for(const extra of EXTRAS.filter(item=>item.taxonId===taxon.id)){
      const format=fmtOf(extra.fmt)
      const {status,reason}=statusFor(taxon,'X')
      rows.push({code:`${taxon.id}.X${extra.n}`,taxonId:taxon.id,series:`X${extra.n}`,title:`${taxon.short}: ${extra.title}`,role:extra.role,mediaKind:extra.kind,evidenceClass:extra.cls,wave:4,ratio:format.ratio,size:format.size,status,statusReason:reason,specimenRef:extra.specimen??specimenRef,brief:extra.brief,promptFile:extra.cls==='D'?PROMPT_FILE(taxon.id):''})
    }
  }
  for(const taxon of TAXA){
    const l=taxon.lithics
    const kind:MediaKindName='specimen-photo'
    const specimenRef=l?`${l.industry} — type sites: ${l.typeSites.join('; ')}`:''
    const specs:{n:number;title:string;cls:EvidenceClass;mk:MediaKindName;role:string;fmt:keyof typeof FORMAT;brief:string}[]=[
      {n:1,title:`${taxon.short}: stone-tool kit (flat lay with scale)`,cls:'C',mk:kind,role:'behavior',fmt:'plate',
        brief:l?`Licensed photograph of dated artefacts from the ${l.industry}: ${l.kit.join('; ')}. Flat lay on a neutral background with a scale bar; each artefact with site, layer and age. Search terms: ${l.searchTerms.join(' | ')}. Attribution caution: ${l.attribution} ${SOURCE_ORDER}`:''},
      {n:2,title:`${taxon.short}: key tool type — ${l?l.keyType:'none'}`,cls:'C',mk:kind,role:'specimen-reference',fmt:'plate',
        brief:l?`Licensed photograph of one dated artefact (${l.keyType}), both faces, with a scale bar. Type sites: ${l.typeSites.join('; ')}. ${l.caution} ${SOURCE_ORDER}`:''},
      {n:3,title:`${taxon.short}: how the tools were made`,cls:'B',mk:'context-schematic',role:'anatomy-plate',fmt:'vector',
        brief:l?`Vector diagram of the reduction sequence: ${l.sequence}. Drawn from licensed artefact images or experimental-replication photographs; labels from claim records. ${l.caution}`:''},
    ]
    for(const spec of specs){
      const format=fmtOf(spec.fmt)
      const {status,reason}=statusFor(taxon,`L${spec.n}`)
      rows.push({code:`${taxon.id}.L${spec.n}`,taxonId:taxon.id,series:`L${spec.n}`,title:spec.title,role:spec.role,mediaKind:spec.mk,evidenceClass:spec.cls,wave:6,ratio:format.ratio,size:format.size,status,statusReason:reason,specimenRef,brief:status==='NOT-APPLICABLE'?`Not applicable: ${reason}`:spec.brief,promptFile:''})
    }
  }
  for(const item of COMPARATIVE){
    const format=item.cls==='A'||item.cls==='B'?FORMAT.vector:FORMAT.plate
    rows.push({code:`compare.C${pad(item.n)}`,taxonId:null,series:`C${pad(item.n)}`,title:item.title,role:'comparative-morphology',mediaKind:item.kind,evidenceClass:item.cls,wave:5,ratio:format.ratio,size:format.size,status:'TODO',statusReason:'',specimenRef:'',brief:item.brief,promptFile:''})
  }
  return rows
}

/* ---------------------------------------------------------------- prompts (class D) */

const CONVENTIONS=[
  'EVIDENCE TIERS. BONE-ANCHORED = directly constrained by the fossils: render with confidence. INFERRED = reasoned from related species and ecology: render plausibly but unobtrusively. CONVENTION = not knowable: use the convention stated for this taxon and add no striking detail.',
  'SOFT TISSUE: follow standard forensic facial-approximation soft-tissue depths at craniometric landmarks; no exaggeration of muscle, fat, lips or nose beyond what the skeleton supports.',
  'EYES: dark brown irises. For non-Homo hominins keep the sclera (eye white) pigmented rather than bright white; for Homo a light sclera is acceptable. This is a convention, not a finding.',
  'EXPRESSION: neutral and calm. Not aggressive, not smiling, no ape-like grimace, no “caveman” trope.',
  'NO RACIAL CARICATURE: do not mimic any living ethnic group; keep pigmentation and hair exactly as the convention says.',
  'NON-SEXUALISED (strict): no visible genitals and no full-frontal nudity in any image. Non-Homo hominins: dense short body hair covering torso and hips, plus posture and distance. Homo: the waist wrap stated in the clothing convention, plus posture; never a bare, hairless full-frontal body.',
]

const MUST_NOT=[
  'any text, caption, label, signature, watermark, logo, border or frame',
  'modern objects: clothing, jewellery, metal, woven textiles, ceramics, glasses, tattoos, modern haircuts or beard styling',
  'domesticated animals or crops',
  'fire, weapons or tools unless this brief explicitly lists them',
  'monstrous, brutish or “ape-man” stylisation; glowing eyes; dramatic cinematic lens flares',
  'more individuals than specified; any hominin in a habitat-only image',
  'visible genitals, full-frontal nudity, or hairless bare bodies',
]

const SELF_CHECK=(extra:string)=>`Before you output the final image, silently verify: (1) aspect ratio is exactly as specified; (2) every BONE-ANCHORED feature listed is visible and correct; (3) nothing from MUST NOT appears; (4) there is no text anywhere in the image; (5) skin, hair and clothing follow the stated convention; ${extra}. If any check fails, regenerate.`

const AFTER=`After the image, add an ASSUMPTIONS list of at most 120 words stating which features you rendered as BONE-ANCHORED, INFERRED and CONVENTION. Do not claim anything you did not do.`

const bullets=(items:string[])=>items.map(item=>`- ${item}`).join('\n')

const reference=(t:TaxonBrief)=>
`REFERENCE INPUT (optional; attach if the tool accepts images): (a) a lateral-view photograph or render of ${t.basis.primary}; (b) a frontal-view photograph or render of the same specimen; (c) a modern human skull in the same view and at the same scale, for proportion only. If nothing is attached, follow the written morphology literally and say so in the assumptions list.`

const header=(code:string,title:string,t:TaxonBrief,cls:string,ratio:string,size:string)=>
`### ${code} — ${title}
Evidence class ${cls} (reconstruction) · ${ratio} · ${size} · basis: ${t.basis.primary}
Copy everything inside the box below into the image tool.`

const box=(text:string)=>'```text\n'+text.trim()+'\n```'

function portrait(t:TaxonBrief):string{
  if(t.noCranium){
    return `${header(`${t.id}.S02`,`${t.short}: portrait (bone-inventory silhouette)`,t,'D',FORMAT.portrait.ratio,FORMAT.portrait.size)}

${box(`Create ONE scientific illustration for a science-education atlas of human evolution (Human Origins): a bone-inventory silhouette of ${t.name}.
OUTPUT: single image, portrait 4:5, 1000×1250 px, plain neutral dark-grey background.
WHY THIS FORMAT: no cranium of ${t.short} is known (${t.basis.primary}). A face MUST NOT be invented.
TASK: draw a flat, softly shaded full-body outline of a small, chimpanzee-sized bipedal-capable hominin in profile, as a uniform mid-grey silhouette with NO face, NO eyes, NO nose, NO mouth, NO hair texture and NO skin detail. Inside the silhouette render, as realistic ivory-coloured bones, ONLY the elements that exist: ${t.keyBones.join('; ')}; leave the rest of the silhouette empty.
BONE-ANCHORED FEATURES:
${bullets(t.bone)}
DO NOT INVENT:
${bullets(t.unknown)}
STYLE: restrained scientific-plate style, soft top-left light, muted palette, generous empty margin.
${bullets(['MUST NOT include: '+MUST_NOT.join('; ')]).slice(2)}
${SELF_CHECK('(6) the head is a blank, featureless shape; (7) only the listed bones are drawn')}
${AFTER}`)}`
  }
  return `${header(`${t.id}.S02`,`${t.short}: portrait`,t,'D',FORMAT.portrait.ratio,FORMAT.portrait.size)}

${box(`Create ONE scientific paleoart portrait of ${t.name} for a science-education atlas of human evolution (Human Origins). It must be an evidence-based facial reconstruction, not entertainment art.
OUTPUT: single image, portrait 4:5, 1000×1250 px, head and shoulders, three-quarter view, neutral mid-grey seamless background, even soft studio-style light.
SUBJECT: ${t.individual}. Lived ${t.ageText}; region: ${t.region}.
BASIS: ${t.basis.primary}${t.basis.also.length?`; also consulted: ${t.basis.also.join('; ')}`:''}.
${reference(t)}
BONE-ANCHORED FEATURES (render with confidence):
${bullets(t.bone)}
SIZE REFERENCE: braincase ${t.brain}. BODY: ${t.body}.
DO NOT INVENT (leave unremarkable and do not add striking detail):
${bullets(t.unknown)}
CONVENTIONS FOR THIS TAXON (not findings): skin and hair — ${t.skinHair}. Clothing — ${t.clothing}.
${bullets(CONVENTIONS)}
STYLE: photorealistic, restrained documentary-style paleoart; natural skin texture; muted palette; no dramatic lighting.
MUST NOT include: ${MUST_NOT.join('; ')}.
${SELF_CHECK('(6) exactly one individual is shown')}
${AFTER}`)}`
}

function hero(t:TaxonBrief):string{
  const empty=!!t.noCranium
  const scene=empty
    ?`Create ONE wide landscape image of the paleoenvironment of ${t.name}: ${t.heroScene}.`
    :`Create ONE wide scientific paleoart scene for ${t.name}.`
  return `${header(`${t.id}.S03`,`${t.short}: dossier hero`,t,'D',FORMAT.hero.ratio,FORMAT.hero.size)}

${box(`${scene} This image is for a science-education atlas of human evolution (Human Origins); it must be evidence-based, not entertainment art.
OUTPUT: single image, 16:9, 1920×1080 px, wide landscape composition, horizon in the upper third, natural daylight.
TIME AND PLACE: ${t.ageText}; ${t.region}.
SCENE: ${t.heroScene}.
${empty?'NO hominin figure appears in this image.':`Individuals are small in the frame (each under one third of the image height) so the environment dominates. Show exactly the individuals described in SCENE, no more.
REFERENCE INPUT (optional): the previously generated portrait of this species, if you have one, for head and body proportions. Otherwise follow the morphology below literally.
BONE-ANCHORED FEATURES OF THE INDIVIDUALS:
${bullets(t.bone)}
BODY: ${t.body}.
CONVENTIONS (not findings): skin and hair — ${t.skinHair}. Clothing — ${t.clothing}.`}
ENVIRONMENT: ${t.habitat.setting}. Vegetation: ${t.habitat.flora}. Animals (kinds only; do not add modern iconic species): ${t.habitat.fauna.replace(/^kinds only:\s*/,'')}. Climate and season: ${t.habitat.climate}.
BEHAVIOUR: only calm everyday activity (foraging, resting, walking, drinking). No hunting, no violence, no ritual, no tools or fire unless listed in SCENE.
${bullets(CONVENTIONS)}
STYLE: photorealistic, restrained documentary-style paleoart; muted natural palette; no lens flares.
MUST NOT include: ${MUST_NOT.slice(0,5).join('; ')}.
${SELF_CHECK(empty?'(6) there is no hominin figure':'(6) the number and relative size of individuals match SCENE')}
${AFTER}`)}`
}

function habitat(t:TaxonBrief):string{
  return `${header(`${t.id}.S10`,`${t.short}: habitat`,t,'D',FORMAT.hero.ratio,FORMAT.hero.size)}

${box(`Create ONE landscape image of the paleoenvironment where ${t.name} lived. This image is for a science-education atlas of human evolution (Human Origins); it must be evidence-based, not entertainment art.
OUTPUT: single image, 16:9, 1920×1080 px, natural daylight, wide landscape.
TIME AND PLACE: ${t.ageText}; ${t.region}.
SETTING: ${t.habitat.setting}.
VEGETATION: ${t.habitat.flora}. Depict plant KINDS and growth forms appropriate to the period; do not add crops, ornamental or modern invasive plants.
ANIMALS (kinds only, small in the frame; do not add modern iconic species): ${t.habitat.fauna.replace(/^kinds only:\s*/,'')}.
CLIMATE AND SEASON: ${t.habitat.climate}.
NO hominin figures, NO tools, NO fire, NO footprints and NO structures appear in this image. It is a habitat-only plate.
STYLE: photorealistic, restrained documentary-style landscape; muted natural palette; no lens flares, no glowing sky.
MUST NOT include: ${MUST_NOT.filter((_,i)=>i!==5).join('; ')}; any hominin.
${SELF_CHECK('(6) no hominin appears')}
${AFTER}`)}`
}

function behavior(t:TaxonBrief):string{
  const b=t.behavior!
  return `${header(`${t.id}.S11`,`${t.short}: ${b.title}`,t,'D',FORMAT.plate.ratio,FORMAT.plate.size)}

${box(`Create ONE scientific paleoart scene: ${b.title}, for ${t.name}. This image is for a science-education atlas of human evolution (Human Origins); it must be evidence-based, not entertainment art.
OUTPUT: single image, 4:3, 1600×1200 px, natural daylight, medium-wide shot, subjects occupy about half of the frame height.
EVIDENCE THIS SCENE RESTS ON: ${b.evidence}.
SCENE: ${b.scene}.
OBJECTS AND TOOLS (exactly these, drawn accurately for the period): ${b.objects}.
CAUTION: ${b.caution}.
REFERENCE INPUT (optional): the previously generated portrait of this species, if you have one, for head and body proportions, and a photograph of the real artefact type listed below. Otherwise follow the morphology below literally.
BONE-ANCHORED FEATURES OF THE INDIVIDUALS:
${bullets(t.bone)}
BODY: ${t.body}.
CONVENTIONS (not findings): skin and hair — ${t.skinHair}. Clothing — ${t.clothing}.
ENVIRONMENT: ${t.habitat.setting}; vegetation: ${t.habitat.flora}; climate: ${t.habitat.climate}.
${bullets(CONVENTIONS)}
STYLE: photorealistic, restrained documentary-style paleoart; muted natural palette; no gore; no lens flares.
MUST NOT include: ${MUST_NOT.slice(0,3).join('; ')}; weapons or tools not listed above; animals being killed.
${SELF_CHECK('(6) only the listed objects and tools appear, drawn in period-appropriate form')}
${AFTER}`)}`
}

function irhoud(t:TaxonBrief):string{
  return `${header('sapiens.X1','H. sapiens: Jebel Irhoud 1, facial reconstruction',t,'D',FORMAT.portrait.ratio,FORMAT.portrait.size)}

${box(`Create ONE scientific paleoart portrait of an early Homo sapiens based on Jebel Irhoud 1 (Morocco, about 315,000 years ago) for a science-education atlas of human evolution (Human Origins). Evidence-based facial reconstruction, not entertainment art.
OUTPUT: single image, portrait 4:5, 1000×1250 px, head and shoulders, three-quarter view, neutral mid-grey seamless background, even soft light.
SUBJECT: one adult; sex not asserted by the specimen — draw an adult male as a visual convention (verify in the specimen record).
REFERENCE INPUT (attach if the tool accepts images; otherwise follow the written morphology literally and say so): lateral and frontal views of Jebel Irhoud 1, and a modern human skull in the same view for proportion only.
BONE-ANCHORED FEATURES (render with confidence; verify against the publications):
- a face that is short, flat and tucked beneath the braincase, similar to modern humans
- a long, low braincase that is NOT globular, with a receding forehead (unlike later modern humans)
- a moderate, continuous brow ridge more pronounced than in recent humans
- large teeth relative to recent humans
- braincase size about 1,300–1,400 cc (verify)
DO NOT INVENT: nose and lip soft tissue; skin, hair and eye colour; facial hair; ornament.
CONVENTIONS (not findings): medium to dark brown skin; dark, straight-to-wavy hair, loose or simply tied; no clothing visible at head-and-shoulders framing.
${bullets(CONVENTIONS)}
STYLE: photorealistic, restrained documentary-style paleoart; natural skin texture; muted palette.
MUST NOT include: ${MUST_NOT.join('; ')}.
${SELF_CHECK('(6) exactly one individual is shown; (7) the braincase is long and low, not globular')}
${AFTER}`)}`
}

/** Editorial “verify” notes are for humans (see taxa.ts); they must not reach the image tool. */
const scrub=(text:string)=>text
  .replace(/\s*\((?:kinds only;\s*)?verify[^)]*\)/g,'')
  .replace(/;\s*verify[^)]*\)/g,')')
  .replace(/,\s*verify[^)]*\)/g,')')

export function composePromptFiles():Record<string,string>{
  const files:Record<string,string>={}
  for(const t of TAXA){
    const parts:string[]=[`# ${t.name} — image prompts (class D)

Generated by \`npm run images:build\` from \`tools/images/taxa.ts\` and \`tools/images/spec.ts\`. **Do not edit this file by hand.** Read \`_global.md\` first. Each prompt below is self-contained.
`]
    parts.push(portrait(t),hero(t),habitat(t))
    if(t.behavior) parts.push(behavior(t))
    if(t.id==='sapiens') parts.push(irhoud(t))
    files[PROMPT_FILE(t.id)]=scrub(parts.join('\n\n')+'\n')
  }
  files['prompts/_global.md']=GLOBAL_DOC
  files['prompts/ALL.md']=composeAll(files)
  return files
}

/** One clean file: heading + copy-ready box per prompt, in path order, nothing else. */
function composeAll(files:Record<string,string>):string{
  const blocked=new Set(buildCatalog().filter(row=>row.status==='BLOCKED-NO-SPECIMEN').map(row=>row.code))
  const out:string[]=['# Human Origins — image prompts (all, in order)\n']
  for(const t of TAXA){
    out.push(`## ${t.name}\n`)
    const sections=files[PROMPT_FILE(t.id)].split('\n### ').slice(1)
    for(const section of sections){
      const heading=section.split('\n')[0]
      const code=heading.split(' — ')[0]
      const box=/```text\n[\s\S]*?\n```/.exec(section)![0]
      out.push(`### ${heading}${blocked.has(code)?' [on hold: specimen record not yet registered]':''}\n\n${box}\n`)
    }
  }
  return out.join('\n')
}

const GLOBAL_DOC=`# Image prompts — read me first

**Purpose.** Self-contained prompts for the class-D images of the Human Origins atlas (portraits, hero scenes, habitats, documented-behaviour scenes). They work in ChatGPT (image generation) or any generator that accepts a long text prompt, and they double as a brief for an artist or 3D modeller.

**What AI may and may not make.**
- Class D only (reconstructions). Never class C (photographs of real specimens, sites, artefacts): a generated image of a fossil would be fabricated evidence.
- Every output is a **draft** until a reviewer signs the checklist below. Publish only with \`evidenceClass: reconstruction\`, a visible “reconstruction” label, the assumptions list and the reviewer.

**How to use a prompt (ChatGPT or similar).**
1. Open a new conversation for each image (so earlier images do not leak into it).
2. Attach the reference images named in REFERENCE INPUT (rendered or photographed from licensed scans; see classes B and C in the catalog). If you cannot attach them, say so; the prompt still works from the written morphology, but expect lower accuracy.
3. Paste everything inside the box. Ask for **one** image.
4. If the result breaks a rule, reply with the specific failed check and ask for a regeneration. Do not accept “close enough” on a BONE-ANCHORED feature.
5. Save the image and fill the assumptions sheet (below). Upload through the CMS (admin → Media) only after review.

**Project conventions (apply to every prompt).**
- Skin, hair and eye colour are not preserved in fossils. The conventions in each prompt are stated as conventions, never as findings.
- Neutral expression, non-sexualised framing, no racial caricature, no text or watermark in the image.
- Fauna are given as *kinds*; the species must be verified against the site faunal list before publication.

**Assumptions sheet (fill for every published image).**
\`\`\`text
image code:
generator and version:
date:
prompt file and prompt id:
reference images used (code, licence):
bone-anchored features confirmed visible (list):
conventions applied (list):
deviations from the brief and how they were handled:
regenerated N times, reason:
reviewer, date, decision (approve / revise / reject):
\`\`\`

**Reviewer checklist.**
1. Every BONE-ANCHORED feature is visible and correct against the reference scans.
2. Nothing under DO NOT INVENT has been rendered as a striking, specific detail.
3. No anachronism (objects, tools, fire, clothing) beyond what the brief lists.
4. Skin, hair, eye colour follow the stated convention; no stereotype.
5. Fauna kinds match the verified site faunal list.
6. The caption says “reconstruction”, names the specimen basis and lists the main uncertainties.
7. Licence and credit fields are complete (the generator’s terms allow this use).
`
